-- Generated from user's original MSSQL script. Run once in a NEW / EMPTY Supabase database.
-- Uses public schema, quoted original table and column names to preserve exact casing.
-- Do not run on an existing populated production DB without a backup.
BEGIN;
SET search_path TO public;

CREATE TABLE IF NOT EXISTS public."Roles" (
  "RoleId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(60) NOT NULL,
  "Name" varchar(150) NOT NULL,
  PRIMARY KEY ("RoleId")
);

CREATE TABLE IF NOT EXISTS public."Permissions" (
  "PermissionId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(100) NOT NULL,
  "Description" varchar(240),
  PRIMARY KEY ("PermissionId")
);

CREATE TABLE IF NOT EXISTS public."RolePermissions" (
  "RoleId" integer NOT NULL,
  "PermissionId" integer NOT NULL,
  CONSTRAINT "PK_RolePermissions" PRIMARY KEY ("RoleId", "PermissionId")
);

CREATE TABLE IF NOT EXISTS public."Users" (
  "UserId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Username" varchar(80) NOT NULL,
  "PasswordHash" varchar(255) NOT NULL,
  "DisplayName" varchar(160) NOT NULL,
  "DepartmentId" integer,
  "IsActive" boolean NOT NULL,
  "CreatedAt" timestamp NOT NULL,
  "UpdatedAt" timestamp NOT NULL,
  PRIMARY KEY ("UserId")
);

CREATE TABLE IF NOT EXISTS public."UserRoles" (
  "UserId" bigint NOT NULL,
  "RoleId" integer NOT NULL,
  CONSTRAINT "PK_UserRoles" PRIMARY KEY ("UserId", "RoleId")
);

CREATE TABLE IF NOT EXISTS public."Departments" (
  "DepartmentId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(40) NOT NULL,
  "Name" varchar(160) NOT NULL,
  "IsActive" boolean NOT NULL,
  PRIMARY KEY ("DepartmentId")
);

CREATE TABLE IF NOT EXISTS public."WorkflowStates" (
  "StateCode" varchar(50) NOT NULL,
  "StateName" varchar(140) NOT NULL,
  "IsTerminal" boolean NOT NULL,
  PRIMARY KEY ("StateCode")
);

CREATE TABLE IF NOT EXISTS public."Events" (
  "EventId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "TicketCode" text GENERATED ALWAYS AS ('EVT-' || lpad("EventId"::text, 8, '0')) STORED,
  "Title" varchar(240) NOT NULL,
  "Description" varchar,
  "OrganizerDepartmentId" integer NOT NULL,
  "CreatedBy" bigint NOT NULL,
  "StartsAt" timestamp,
  "EndsAt" timestamp,
  "ExpectedAttendees" integer,
  "StateCode" varchar(50) NOT NULL,
  "RowVer" bytea DEFAULT decode(substr(md5(random()::text || clock_timestamp()::text), 1, 16), 'hex') NOT NULL,
  "CreatedAt" timestamp NOT NULL,
  "UpdatedAt" timestamp NOT NULL,
  PRIMARY KEY ("EventId")
);

CREATE TABLE IF NOT EXISTS public."BudgetItems" (
  "BudgetItemId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "ItemName" varchar(200) NOT NULL,
  "Quantity" numeric(12, 2) NOT NULL,
  "UnitPrice" numeric(19, 2) NOT NULL,
  "EstimatedAmount" numeric(31,4) GENERATED ALWAYS AS ("Quantity" * "UnitPrice") STORED,
  PRIMARY KEY ("BudgetItemId")
);

CREATE TABLE IF NOT EXISTS public."AuditLogs" (
  "AuditId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ActorId" bigint,
  "EntityName" varchar(80) NOT NULL,
  "EntityId" varchar(80) NOT NULL,
  "ActionCode" varchar(80) NOT NULL,
  "Details" varchar,
  "AtUtc" timestamp NOT NULL,
  PRIMARY KEY ("AuditId")
);

CREATE TABLE IF NOT EXISTS public."Equipment" (
  "EquipmentId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(40) NOT NULL,
  "Name" varchar(160) NOT NULL,
  "TotalQuantity" integer NOT NULL,
  "IsActive" boolean NOT NULL,
  PRIMARY KEY ("EquipmentId")
);

CREATE TABLE IF NOT EXISTS public."EquipmentHandovers" (
  "HandoverId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "RequestId" bigint NOT NULL,
  "HandoverType" varchar(12) NOT NULL,
  "ConditionNote" varchar(1000),
  "EvidenceDocumentId" bigint,
  "RecordedBy" bigint NOT NULL,
  "RecordedAt" timestamp NOT NULL,
  PRIMARY KEY ("HandoverId")
);

CREATE TABLE IF NOT EXISTS public."EquipmentRequests" (
  "RequestId" bigint NOT NULL,
  "EquipmentId" integer NOT NULL,
  "Quantity" integer NOT NULL,
  CONSTRAINT "PK_EquipmentRequests" PRIMARY KEY ("RequestId", "EquipmentId")
);

CREATE TABLE IF NOT EXISTS public."EventDocuments" (
  "DocumentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "DocumentType" varchar(50) NOT NULL,
  "OriginalFileName" varchar(255) NOT NULL,
  "StorageKey" varchar(500) NOT NULL,
  "MimeType" varchar(120) NOT NULL,
  "FileSizeBytes" bigint NOT NULL,
  "UploadedBy" bigint NOT NULL,
  "UploadedAt" timestamp NOT NULL,
  PRIMARY KEY ("DocumentId")
);

CREATE TABLE IF NOT EXISTS public."EventPlans" (
  "EventId" bigint NOT NULL,
  "Objectives" varchar,
  "ProgramContent" varchar,
  "Timeline" varchar,
  "Staffing" varchar,
  "RiskPlan" varchar,
  "UpdatedAt" timestamp NOT NULL,
  PRIMARY KEY ("EventId")
);

CREATE TABLE IF NOT EXISTS public."EventReports" (
  "ReportId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "Content" varchar,
  "IsRequired" boolean NOT NULL,
  "IsConfirmed" boolean NOT NULL,
  "SubmittedAt" timestamp,
  "ConfirmedBy" bigint,
  PRIMARY KEY ("ReportId")
);

CREATE TABLE IF NOT EXISTS public."Facilities" (
  "FacilityId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(40) NOT NULL,
  "Name" varchar(160) NOT NULL,
  "Capacity" integer,
  "IsActive" boolean NOT NULL,
  PRIMARY KEY ("FacilityId")
);

CREATE TABLE IF NOT EXISTS public."FacilityRequests" (
  "RequestId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "RequestedBy" bigint NOT NULL,
  "RequestedAt" timestamp NOT NULL,
  "Status" varchar(25) NOT NULL,
  "Note" varchar(1000),
  PRIMARY KEY ("RequestId")
);

CREATE TABLE IF NOT EXISTS public."FacilityReservations" (
  "ReservationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "RequestId" bigint NOT NULL,
  "FacilityId" integer NOT NULL,
  "StartsAt" timestamp NOT NULL,
  "EndsAt" timestamp NOT NULL,
  "Status" varchar(20) NOT NULL,
  PRIMARY KEY ("ReservationId")
);

CREATE TABLE IF NOT EXISTS public."FinancialDocuments" (
  "FinancialDocumentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "PaymentRequestId" bigint NOT NULL,
  "DocumentId" bigint NOT NULL,
  PRIMARY KEY ("FinancialDocumentId")
);

CREATE TABLE IF NOT EXISTS public."Notifications" (
  "NotificationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "RecipientUserId" bigint NOT NULL,
  "EventId" bigint,
  "Title" varchar(200) NOT NULL,
  "Body" varchar(1000),
  "IsRead" boolean NOT NULL,
  "CreatedAt" timestamp NOT NULL,
  PRIMARY KEY ("NotificationId")
);

CREATE TABLE IF NOT EXISTS public."PaymentRequests" (
  "PaymentRequestId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "Amount" numeric(19, 2) NOT NULL,
  "Status" varchar(30) NOT NULL,
  "SubmittedBy" bigint NOT NULL,
  "ApprovedBy" bigint,
  "ApprovedAt" timestamp,
  "PaidAt" timestamp,
  PRIMARY KEY ("PaymentRequestId")
);

CREATE TABLE IF NOT EXISTS public."WorkflowHistory" (
  "HistoryId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "EventId" bigint NOT NULL,
  "FromState" varchar(50),
  "ToState" varchar(50) NOT NULL,
  "ActionCode" varchar(60) NOT NULL,
  "ActorId" bigint NOT NULL,
  "Comment" varchar(2000),
  "PerformedAt" timestamp NOT NULL,
  PRIMARY KEY ("HistoryId")
);

CREATE TABLE IF NOT EXISTS public."WorkflowTransitions" (
  "TransitionId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FromState" varchar(50) NOT NULL,
  "ActionCode" varchar(60) NOT NULL,
  "ToState" varchar(50) NOT NULL,
  "RequiredPermission" varchar(100) NOT NULL,
