CREATE OR REPLACE VIEW public."v_UserPermissions" AS
SELECT DISTINCT u."UserId", u."Username", r."Code" AS "RoleCode", p."Code" AS "PermissionCode"
FROM public."Users" u
JOIN public."UserRoles" ur ON ur."UserId"=u."UserId"
JOIN public."Roles" r ON r."RoleId"=ur."RoleId"
JOIN public."RolePermissions" rp ON rp."RoleId"=r."RoleId"
JOIN public."Permissions" p ON p."PermissionId"=rp."PermissionId"
WHERE u."IsActive"=true;

CREATE OR REPLACE VIEW public."v_EventOverview" AS
SELECT e."EventId",e."TicketCode",e."Title",e."StateCode",s."StateName",d."Name" AS "DepartmentName",
e."StartsAt",e."EndsAt",e."CreatedAt",u."DisplayName" AS "CreatedByName",
COALESCE((SELECT SUM(b."EstimatedAmount") FROM public."BudgetItems" b WHERE b."EventId"=e."EventId"),0) AS "EstimatedBudget"
FROM public."Events" e
JOIN public."WorkflowStates" s ON s."StateCode"=e."StateCode"
JOIN public."Departments" d ON d."DepartmentId"=e."OrganizerDepartmentId"
JOIN public."Users" u ON u."UserId"=e."CreatedBy";

CREATE OR REPLACE VIEW public."v_RoleMenuPermissions" AS
SELECT DISTINCT r."Code" AS "RoleCode",p."Code" AS "PermissionCode"
FROM public."Roles" r
JOIN public."RolePermissions" rp ON rp."RoleId"=r."RoleId"
JOIN public."Permissions" p ON p."PermissionId"=rp."PermissionId";

-- SQL Server rowversion analogue: refresh opaque 8-byte token on each UPDATE.
CREATE OR REPLACE FUNCTION public."fn_Events_rowver"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW."RowVer" := decode(substr(md5(random()::text || clock_timestamp()::text), 1, 16), 'hex');
  RETURN NEW;
END; $$;
CREATE TRIGGER "tr_Events_rowver" BEFORE UPDATE ON public."Events"
FOR EACH ROW EXECUTE FUNCTION public."fn_Events_rowver"();

-- Equivalent of dbo.usp_ReserveFacility: call SELECT public."usp_ReserveFacility"(...).
-- The facility row lock serializes concurrent reservations for the same facility.
CREATE OR REPLACE FUNCTION public."usp_ReserveFacility"(
  p_RequestId bigint, p_FacilityId integer, p_StartsAt timestamp(0), p_EndsAt timestamp(0)
) RETURNS bigint LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_reservationId bigint;
BEGIN
  IF p_StartsAt >= p_EndsAt THEN
    RAISE EXCEPTION 'Khoảng thời gian không hợp lệ.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "FacilityRequests" WHERE "RequestId"=p_RequestId) THEN
    RAISE EXCEPTION 'Yêu cầu không tồn tại.';
  END IF;
  PERFORM 1 FROM "Facilities" WHERE "FacilityId"=p_FacilityId AND "IsActive"=true FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Địa điểm không tồn tại hoặc không hoạt động.';
  END IF;
  IF EXISTS (SELECT 1 FROM "FacilityReservations"
    WHERE "FacilityId"=p_FacilityId AND "Status" IN ('HELD','CONFIRMED')
      AND "StartsAt" < p_EndsAt AND "EndsAt" > p_StartsAt) THEN
    RAISE EXCEPTION 'Địa điểm đã được giữ hoặc đặt trong thời gian này.';
  END IF;
  INSERT INTO "FacilityReservations"("RequestId","FacilityId","StartsAt","EndsAt","Status")
  VALUES(p_RequestId,p_FacilityId,p_StartsAt,p_EndsAt,'HELD')
  RETURNING "ReservationId" INTO v_reservationId;
  RETURN v_reservationId;
END; $$;

-- Equivalent of dbo.usp_TransitionEvent: call SELECT public."usp_TransitionEvent"(event_id, actor_id, action, comment).
CREATE OR REPLACE FUNCTION public."usp_TransitionEvent"(
  p_EventId bigint, p_ActorId bigint, p_ActionCode varchar(60), p_Comment varchar(2000) DEFAULT NULL
) RETURNS TABLE("EventId" bigint,"PreviousState" varchar(50),"CurrentState" varchar(50))
LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_old varchar(50); v_next varchar(50); v_perm varchar(100); v_dept integer; v_owner bigint;
BEGIN
  SELECT e."StateCode",e."OrganizerDepartmentId",e."CreatedBy" INTO v_old,v_dept,v_owner
  FROM "Events" e WHERE e."EventId"=p_EventId FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Hồ sơ không tồn tại.'; END IF;
  SELECT wt."ToState",wt."RequiredPermission" INTO v_next,v_perm
  FROM "WorkflowTransitions" wt WHERE wt."FromState"=v_old AND wt."ActionCode"=p_ActionCode;
  IF NOT FOUND THEN RAISE EXCEPTION 'Thao tác không hợp lệ ở trạng thái hiện tại.'; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" u WHERE u."UserId"=p_ActorId AND u."IsActive"=true) THEN
    RAISE EXCEPTION 'Tài khoản không hoạt động.';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM "UserRoles" ur
      JOIN "RolePermissions" rp ON rp."RoleId"=ur."RoleId"
      JOIN "Permissions" p ON p."PermissionId"=rp."PermissionId"
      WHERE ur."UserId"=p_ActorId AND p."Code"=v_perm) THEN
    RAISE EXCEPTION 'Không có quyền thực hiện.';
  END IF;
  IF v_perm IN ('events.edit','events.submit','facilities.request','reports.create','payments.submit')
      AND v_owner <> p_ActorId THEN
    RAISE EXCEPTION 'Chỉ người tạo hồ sơ được gửi hoặc sửa ở mẫu này.';
  END IF;
  IF v_perm='approvals.department.decide' AND NOT EXISTS(
    SELECT 1 FROM "Users" u WHERE u."UserId"=p_ActorId AND u."DepartmentId"=v_dept) THEN
    RAISE EXCEPTION 'Không thuộc đơn vị quản lý hồ sơ.';
  END IF;
  IF p_ActionCode IN ('REJECT','REQUEST_REVISION','REQUEST_DOCUMENTS')
      AND nullif(btrim(p_Comment),'') IS NULL THEN
    RAISE EXCEPTION 'Cần ghi lý do hoặc góp ý.';
  END IF;
  UPDATE "Events" e SET "StateCode"=v_next,"UpdatedAt"=(now() AT TIME ZONE 'UTC') WHERE e."EventId"=p_EventId;
  INSERT INTO "WorkflowHistory"("EventId","FromState","ToState","ActionCode","ActorId","Comment")
  VALUES(p_EventId,v_old,v_next,p_ActionCode,p_ActorId,p_Comment);
  INSERT INTO "AuditLogs"("ActorId","EntityName","EntityId","ActionCode","Details")
  VALUES(p_ActorId,'Events',p_EventId::text,p_ActionCode,v_old || ' -> ' || v_next);
  RETURN QUERY SELECT p_EventId,v_old,v_next;
END; $$;

COMMIT;

